import{_ as t,o as s,c as o,ai as r}from"./chunks/framework.C33Uq6m-.js";const m=JSON.parse('{"title":"Historique IA Local","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/history.md","filePath":"fr/guide/history.md"}'),n={name:"fr/guide/history.md"};function a(i,e,l,d,u,c){return s(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="historique-ia-local" tabindex="-1">Historique IA Local <a class="header-anchor" href="#historique-ia-local" aria-label="Permalink to &quot;Historique IA Local&quot;">​</a></h1><p>LLMxRay enregistre automatiquement chaque expérience que vous effectuez — benchmarks, comparaisons, conversations, entraînements. Votre archive de recherche, interrogeable et exportable.</p><h2 id="ce-qui-est-enregistre" tabindex="-1">Ce qui est enregistré <a class="header-anchor" href="#ce-qui-est-enregistre" aria-label="Permalink to &quot;Ce qui est enregistré&quot;">​</a></h2><p>Chaque interaction avec un modèle produit une entrée d&#39;historique. Le tableau ci-dessous montre les données capturées pour chaque type.</p><table tabindex="0"><thead><tr><th>Type d&#39;entrée</th><th>Données capturées</th></tr></thead><tbody><tr><td>Benchmark</td><td>Nom de la suite, modèle, questions, réponses, scores de précision, résultats par catégorie, durée</td></tr><tr><td>Comparaison</td><td>Prompt, modèles comparés, sorties, Token Tax, latence, scores de confiance</td></tr><tr><td>Comparaison de langues</td><td>Prompt, langues testées, modèle, sorties par langue, métriques de qualité</td></tr><tr><td>Session de chat</td><td>Conversation complète (tous les tours), modèle, horodatages, nombre de tokens, latence par token</td></tr><tr><td>Entraînement</td><td>Nom du jeu de données, modèle, paramètres d&#39;entraînement, courbe de perte, nombre d&#39;époques, durée</td></tr><tr><td>Plongement</td><td>Texte d&#39;entrée, modèle, dimensions du vecteur, scores de similarité</td></tr><tr><td>Atelier d&#39;outils</td><td>Définitions d&#39;outils, entrées de test, réponses du modèle, résultats d&#39;exécution</td></tr></tbody></table><p>Les entrées sont horodatées et associées automatiquement au nom du modèle.</p><h2 id="trouver-vos-donnees" tabindex="-1">Trouver vos données <a class="header-anchor" href="#trouver-vos-donnees" aria-label="Permalink to &quot;Trouver vos données&quot;">​</a></h2><p>La page Historique fournit des filtres pour affiner votre archive.</p><ul><li><strong>Type</strong> — Afficher uniquement les benchmarks, conversations, comparaisons ou tout autre type d&#39;entrée.</li><li><strong>Modèle</strong> — Filtrer par modèle utilisé (par ex. <code>llama3</code>, <code>deepseek-r1</code>, <code>phi4</code>).</li><li><strong>Langue</strong> — Pour les comparaisons de langues, filtrer par les langues testées.</li><li><strong>Plage de dates</strong> — Choisir une date de début et de fin pour cibler une période spécifique.</li><li><strong>Tags</strong> — Tags personnalisés que vous avez appliqués aux entrées pour votre propre organisation.</li></ul><p>Les filtres se combinent avec une logique ET — sélectionner un modèle et un type affiche uniquement les entrées correspondant aux deux critères.</p><h2 id="analyse-des-tendances" tabindex="-1">Analyse des tendances <a class="header-anchor" href="#analyse-des-tendances" aria-label="Permalink to &quot;Analyse des tendances&quot;">​</a></h2><p>La page Historique inclut un graphique d&#39;activité qui visualise vos expérimentations au fil du temps.</p><ul><li><strong>Activité dans le temps</strong> — Une chronologie montrant combien d&#39;expériences vous avez effectuées par jour ou par semaine. Repérez les pauses ou les pics dans votre recherche.</li><li><strong>Modèles utilisés</strong> — Une répartition des modèles les plus testés. Utile pour voir si vous dépendez trop d&#39;un seul modèle ou si vous explorez largement.</li><li><strong>Tendances à surveiller :</strong><ul><li>Améliorations de la précision au fil des exécutions successives de benchmarks sur le même modèle.</li><li>Changements de latence après des mises à jour de modèle ou des ajustements de paramètres.</li><li>Quel modèle gagne systématiquement les comparaisons pour votre cas d&#39;usage.</li><li>Courbes de perte d&#39;entraînement qui s&#39;aplatissent — signe que davantage d&#39;époques n&#39;aideront pas.</li></ul></li></ul><h2 id="exportation" tabindex="-1">Exportation <a class="header-anchor" href="#exportation" aria-label="Permalink to &quot;Exportation&quot;">​</a></h2><p>Les entrées d&#39;historique peuvent être exportées en deux formats.</p><ul><li><strong>JSON</strong> — Exporte toutes les entrées avec les données structurées complètes. Inclut chaque champ : horodatages, noms de modèles, prompts, sorties, scores, paramètres et tags. Utilisez pour le scripting, la sauvegarde ou la réimportation.</li><li><strong>CSV</strong> — Exporte la vue filtrée actuelle sous forme de données tabulaires. Les colonnes incluent le type d&#39;entrée, le modèle, la date, les métriques résumées (précision, latence, nombre de tokens) et les tags. Ouvrez dans Excel, Google Sheets ou pandas.</li></ul><p>Pour exporter :</p><ol><li>Appliquez des filtres si vous voulez un sous-ensemble (ou laissez sans filtre pour tout exporter).</li><li>Cliquez sur le bouton <strong>Exporter</strong>.</li><li>Choisissez JSON ou CSV — le fichier se télécharge immédiatement.</li></ol><h2 id="gestion-du-stockage" tabindex="-1">Gestion du stockage <a class="header-anchor" href="#gestion-du-stockage" aria-label="Permalink to &quot;Gestion du stockage&quot;">​</a></h2><p>L&#39;historique est stocké dans IndexedDB dans votre navigateur. Cela ne coûte rien et ne nécessite aucun serveur.</p><ul><li><strong>Paramètres de rétention</strong> — Configurez la durée de conservation des entrées. Les options vont de 30 jours à illimité. Les entrées plus anciennes que la fenêtre de rétention sont supprimées automatiquement.</li><li><strong>Effacer l&#39;historique</strong> — Utilisez l&#39;action <strong>Effacer l&#39;historique</strong> pour supprimer toutes les entrées, ou supprimez des entrées individuelles depuis la liste. Cette action est irréversible.</li><li><strong>Estimations de taille</strong> — Une entrée de benchmark typique fait 2-5 Ko. Une session de chat complète fait 5-50 Ko selon la longueur. Des milliers d&#39;entrées tiennent confortablement dans les limites de stockage du navigateur (typiquement 50 Mo+).</li></ul><h2 id="confidentialite" tabindex="-1">Confidentialité <a class="header-anchor" href="#confidentialite" aria-label="Permalink to &quot;Confidentialité&quot;">​</a></h2><blockquote><p>Toutes les données d&#39;historique sont stockées localement dans l&#39;IndexedDB de votre navigateur. Rien n&#39;est envoyé vers un service cloud. Les entrées d&#39;historique sont conservées dans leur propre magasin de données, séparé des résultats de benchmarks, des sessions de chat et des données d&#39;entraînement d&#39;origine. Effacer l&#39;historique n&#39;affecte pas vos autres magasins de données.</p></blockquote>',23)])])}const h=t(n,[["render",a]]);export{m as __pageData,h as default};
